// Verifies Convex's HMAC exactly like lib/domain/signing.ts:
//   X-LendLoop-Signature: v1=<hex(HMAC_SHA256(N8N_WEBHOOK_SECRET, `${timestamp}.${rawBody}`))>
// The signature covers the RAW body bytes (Webhook option "Raw Body"), never a
// re-serialized JSON object, because key order/whitespace would change the MAC.
const crypto = require('crypto');

const TOLERANCE_SEC = 300; // replay window; a replay inside it can at most re-send the same email
const EVENTS = ['requested', 'approved', 'declined', 'cancelled', 'return_reported', 'returned', 'overdue_reminder'];
const STRING_FIELDS = ['idempotencyKey', 'event', 'loanId', 'toolName', 'startDate', 'endDate', 'recipientRole', 'recipientFirstName', 'recipientEmail'];

const item = $input.first();
const headers = item.json.headers || {};
const timestamp = headers['x-lendloop-timestamp'];
const signature = headers['x-lendloop-signature'];

let rawBody = '';
const bin = item.binary && item.binary.data;
if (bin && bin.id) {
  rawBody = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} else if (bin && typeof bin.data === 'string') {
  rawBody = Buffer.from(bin.data, 'base64').toString('utf8');
}

function verify() {
  const secret = $env.N8N_WEBHOOK_SECRET;
  if (!secret) return 'not_configured';
  if (!timestamp || !signature) return 'missing_headers';
  if (!/^\d{1,12}$/.test(timestamp)) return 'bad_timestamp';
  if (Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > TOLERANCE_SEC) return 'stale';
  const m = /^v1=([0-9a-f]{64})$/i.exec(String(signature).trim());
  if (!m) return 'malformed';
  const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`, 'utf8').digest();
  // Both buffers are 32 bytes (regex above), so timingSafeEqual never throws.
  return crypto.timingSafeEqual(expected, Buffer.from(m[1], 'hex')) ? null : 'mismatch';
}

// Keep ONLY the minimized fields Convex is allowed to send; anything extra is dropped.
function project(body) {
  if (!body || typeof body !== 'object') return null;
  const out = {};
  for (const f of STRING_FIELDS) {
    if (typeof body[f] !== 'string' || body[f].length === 0 || body[f].length > 320) return null;
    out[f] = body[f];
  }
  if (!EVENTS.includes(out.event)) return null;
  if (out.recipientRole !== 'owner' && out.recipientRole !== 'borrower') return null;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(out.startDate) || !/^\d{4}-\d{2}-\d{2}$/.test(out.endDate)) return null;
  if (!/^[^\s@]+@[^\s@]+$/.test(out.recipientEmail)) return null;
  out.attempt = Number.isInteger(body.attempt) && body.attempt >= 1 ? body.attempt : 1;
  return out;
}

const reason = verify();
if (reason) {
  // Rejected here without touching Convex. n8n still keeps the execution,
  // bounded by N8N_PAYLOAD_SIZE_MAX and the prune caps (docker-compose.yml).
  console.log(`[lendloop] request-event rejected reason=${reason} execution=${$execution.id}`);
  return [{ json: { signatureValid: false, reason } }];
}

let payload = null;
try {
  payload = project(JSON.parse(rawBody));
} catch (e) {
  payload = null;
}
if (!payload) console.log(`[lendloop] request-event signed but payload incomplete execution=${$execution.id}`);

return [{ json: { signatureValid: true, payloadValid: payload !== null, payload } }];

// Builds the email from the minimized payload only (no description, condition,
// counterpart email or user IDs ever reach n8n).
const p = $('Verify signature').first().json.payload;
const appUrl = String($env.APP_URL || 'http://localhost:3000').replace(/\/+$/, '');
const link = `${appUrl}/loans/${encodeURIComponent(p.loanId)}`;

const fmtDay = (iso) =>
  new Date(`${iso}T00:00:00Z`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' });
const range = `${fmtDay(p.startDate)} – ${fmtDay(p.endDate)}`;
const tool = p.toolName;

const templates = {
  requested: {
    subject: `New borrow request for ${tool}`,
    lines: [`A neighbor would like to borrow your ${tool} (${range}).`, `Approve or decline the request in LendLoop:`],
  },
  approved: {
    subject: `Your request for ${tool} was approved`,
    lines: [`Good news: your request to borrow ${tool} (${range}) was approved.`, `The owner's contact details are now visible on the loan:`],
  },
  declined: {
    subject: `Your request for ${tool} was declined`,
    lines: [`Your request to borrow ${tool} (${range}) was declined.`, `See the details and browse other tools in LendLoop:`],
  },
  cancelled:
    p.recipientRole === 'owner'
      ? {
          subject: `Borrow request for ${tool} was cancelled`,
          lines: [`The borrower cancelled their request for your ${tool} (${range}).`, `The dates are free again. View the loan:`],
        }
      : {
          subject: `Your loan of ${tool} was cancelled`,
          lines: [`Your loan of ${tool} (${range}) was cancelled.`, `View the loan in LendLoop:`],
        },
  return_reported: {
    subject: `${tool} was reported returned`,
    lines: [`The borrower says they've returned your ${tool}.`, `Once you have it back, mark the loan returned in LendLoop:`],
  },
  returned: {
    subject: `Thanks for returning ${tool}`,
    lines: [`The owner marked ${tool} as returned. The loan is closed.`, `View the loan in LendLoop:`],
  },
  overdue_reminder: {
    subject: `Reminder: ${tool} was due back ${fmtDay(p.endDate)}`,
    lines: [`${tool} was due back on ${fmtDay(p.endDate)}. Please return it to the owner.`, `Open the loan in LendLoop:`],
  },
};

const t = templates[p.event];
const text = [
  `Hi ${p.recipientFirstName},`,
  '',
  t.lines[0],
  '',
  t.lines[1],
  link,
  '',
  '— LendLoop',
  `Ref ${p.loanId}. You get this email because you use LendLoop.`,
].join('\n');

return [
  {
    json: {
      from: $env.MAIL_FROM || 'LendLoop <no-reply@lendloop.local>',
      to: p.recipientEmail,
      subject: t.subject,
      text,
    },
  },
];

// Signs the delivery write-back for Convex (POST /n8n/deliveries) with
// CONVEX_INBOUND_SECRET. The HTTP node sends `rawBody` verbatim, so the bytes
// Convex verifies are exactly the bytes signed here.
const crypto = require('crypto');

const secret = $env.CONVEX_INBOUND_SECRET;
if (!secret) throw new Error('CONVEX_INBOUND_SECRET is not set');

const p = $('Verify signature').first().json.payload;
const body = {
  idempotencyKey: p.idempotencyKey,
  status: 'sent',
  attempt: p.attempt,
  executionId: String($execution.id),
  channel: 'email',
};
if (body.status === 'failed') body.errorCategory = 'delivery_failed';

const rawBody = JSON.stringify(body);
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`, 'utf8').digest('hex');

console.log(`[lendloop] delivery ${body.status} key=${body.idempotencyKey} execution=${body.executionId}`);
return [{ json: { idempotencyKey: body.idempotencyKey, rawBody, timestamp, signature } }];

// Signs the delivery write-back for Convex (POST /n8n/deliveries) with
// CONVEX_INBOUND_SECRET. The HTTP node sends `rawBody` verbatim, so the bytes
// Convex verifies are exactly the bytes signed here.
const crypto = require('crypto');

const secret = $env.CONVEX_INBOUND_SECRET;
if (!secret) throw new Error('CONVEX_INBOUND_SECRET is not set');

